begin;
alter table public.curriculum_lessons drop constraint curriculum_lessons_position_check;
alter table public.curriculum_lessons add constraint curriculum_lessons_position_check check (position between 1 and 5);
insert into public.curriculum_lessons(code,block_number,position,title,mission,skill_code,is_published) values('1.4',1,4,'Resolver vocabulario sin perder el hilo','Usa pistas para comprender palabras y decide cuándo consultar un dato exacto.','vocabulary_context',true);
do $seed$
declare item jsonb; new_case_id uuid;
begin
 for item in select value from jsonb_array_elements($cases$[{"variant": "A", "step": 1, "role": "probe", "sentence": "La reserva estaba confirmada, pero faltaba enviar el comprobante.", "question": "¿Qué faltaba pese a la confirmación?", "options": ["Confirmar la reserva", "Enviar el comprobante", "Elegir otra fecha"], "correct_index": 1, "feedback": ["Ya estaba confirmada.", "Sí. «Pero» señala lo pendiente.", "No se habla de otra fecha."]}, {"variant": "A", "step": 2, "role": "probe", "sentence": "El informe era provisional: el equipo lo revisaría antes de publicarlo.", "question": "¿Qué significa «provisional» aquí?", "options": ["Definitivo", "Temporal y sujeto a revisión", "Extraviado"], "correct_index": 1, "feedback": ["Aún faltaba revisarlo.", "Correcto. El texto indica que puede cambiar.", "El informe sí existe."]}, {"variant": "A", "step": 3, "role": "guided", "sentence": "La tienda repuso las botellas agotadas; ahora había suficientes para todos.", "question": "¿Qué hizo al «reponerlas»?", "options": ["Las sustituyó para volver a tener existencias", "Las retiró sin reemplazo", "Las prestó por un día"], "correct_index": 0, "feedback": ["Bien. «Agotadas» y «suficientes» dan la pista.", "Después sí había suficientes.", "No se menciona un préstamo."]}, {"variant": "A", "step": 4, "role": "guided", "sentence": "El aviso decía que la entrega era «inminente», pero no indicaba una fecha. Necesitas estar presente el día exacto.", "question": "¿Qué conviene hacer?", "options": ["Suponer que llegará hoy", "Consultar la fecha antes de organizarte", "Ignorar el aviso porque usa una palabra difícil"], "correct_index": 1, "feedback": ["«Inminente» no da un día exacto.", "Sí. Entiendes que será pronto, pero necesitas precisión.", "El aviso ayuda, aunque no resuelve la fecha."]}, {"variant": "A", "step": 5, "role": "transfer", "sentence": "La respuesta fue escueta: Ana escribió solo la hora y el lugar, sin explicación adicional.", "question": "¿Cómo fue la respuesta?", "options": ["Breve", "Contradictoria", "Extensa"], "correct_index": 0, "feedback": ["Sí. Los dos datos sin explicación permiten inferirlo.", "No hay datos que se contradigan.", "No incluyó una explicación larga."]}, {"variant": "A", "step": 6, "role": "transfer", "sentence": "El reglamento permite una prórroga para entregar la solicitud, pero no indica cuánto dura. Necesitas conocer la fecha límite.", "question": "¿Cuál es la mejor decisión?", "options": ["Dar por hecho que hay una semana", "Consultar la duración exacta de la prórroga", "Cancelar la solicitud sin revisar"], "correct_index": 1, "feedback": ["El texto no fija una semana.", "Correcto. La idea general no basta para decidir una fecha.", "Hay un plazo posible; conviene aclararlo."]}, {"variant": "B", "step": 1, "role": "probe", "sentence": "Aunque llovía, el equipo mantuvo la actividad al aire libre.", "question": "¿Qué ocurrió pese a la lluvia?", "options": ["Canceló la actividad", "La mantuvo", "La cambió a otra semana"], "correct_index": 1, "feedback": ["El texto dice que la mantuvo.", "Sí. «Aunque» presenta el obstáculo.", "No se aplazó."]}, {"variant": "B", "step": 2, "role": "probe", "sentence": "El horario era tentativo: se confirmaría después de hablar con los participantes.", "question": "¿Qué indica «tentativo»?", "options": ["Que todavía puede cambiar", "Que ya es definitivo", "Que nadie participará"], "correct_index": 0, "feedback": ["Bien. La confirmación pendiente es la pista.", "Falta hablar con los participantes.", "No se afirma que se cancele."]}, {"variant": "B", "step": 3, "role": "guided", "sentence": "Nora cotejó dos listas y encontró un nombre que aparecía solo en una.", "question": "¿Qué hizo al «cotejarlas»?", "options": ["Las comparó", "Las destruyó", "Las repartió sin revisarlas"], "correct_index": 0, "feedback": ["Correcto. Encontrar una diferencia revela comparación.", "Las listas seguían disponibles.", "Sí las revisó."]}, {"variant": "B", "step": 4, "role": "guided", "sentence": "La etiqueta dice «perecedero», pero no ofrece una fecha. Necesitas saber si el alimento sigue en buen estado.", "question": "¿Qué conviene comprobar?", "options": ["Solo el color de la etiqueta", "La fecha o las indicaciones de conservación", "El precio original"], "correct_index": 1, "feedback": ["El color no indica la fecha.", "Sí. La palabra orienta, pero no basta para decidir.", "El precio no resuelve la seguridad del alimento."]}, {"variant": "B", "step": 5, "role": "transfer", "sentence": "El grupo optó por una solución austera: usó materiales disponibles y evitó compras nuevas.", "question": "¿Cómo era la solución?", "options": ["Costosa y decorativa", "Sencilla y de pocos recursos", "Imposible de realizar"], "correct_index": 1, "feedback": ["No hicieron compras nuevas.", "Bien. Los detalles precisan el sentido de la palabra.", "Sí lograron aplicarla."]}, {"variant": "B", "step": 6, "role": "transfer", "sentence": "Un aviso exige entregar la constancia «vigente», pero no especifica si acepta una emitida hace seis meses. Tienes ese documento.", "question": "¿Qué harías antes de presentarlo?", "options": ["Verificar el plazo de vigencia aceptado", "Suponer que cualquier constancia sirve", "Ignorar el requisito"], "correct_index": 0, "feedback": ["Correcto. Aquí la precisión afecta el trámite.", "El texto no permite asegurarlo.", "La vigencia es un requisito."]}, {"variant": "C", "step": 1, "role": "probe", "sentence": "La sala parecía vacía, pero todas las mesas estaban reservadas.", "question": "¿Qué aclara «pero»?", "options": ["Había mesas libres", "No había mesas disponibles", "La sala estaba cerrada"], "correct_index": 1, "feedback": ["Estaban reservadas.", "Exacto. La segunda idea cambia la impresión inicial.", "No se afirma que estuviera cerrada."]}, {"variant": "C", "step": 2, "role": "probe", "sentence": "La decisión era preliminar; el comité volvería a discutirla el viernes.", "question": "¿Qué significa «preliminar»?", "options": ["Anterior a la decisión final", "Definitiva e irreversible", "Secreta"], "correct_index": 0, "feedback": ["Sí. La discusión posterior muestra que aún no es final.", "Volverán a discutirla.", "No se habla de secreto."]}, {"variant": "C", "step": 3, "role": "guided", "sentence": "El equipo descartó el primer plan y eligió otro que sí cumplía el presupuesto.", "question": "¿Qué hizo con el primer plan?", "options": ["Lo rechazó", "Lo imprimió", "Lo amplió"], "correct_index": 0, "feedback": ["Correcto. Eligieron otro en su lugar.", "No se menciona impresión.", "No conservaron el primer plan."]}, {"variant": "C", "step": 4, "role": "guided", "sentence": "El mensaje dice que el pago es «parcial», pero no señala el saldo. Necesitas pagar lo restante.", "question": "¿Qué información te falta?", "options": ["El nombre de la persona que escribió", "El importe pendiente", "El color del recibo"], "correct_index": 1, "feedback": ["Eso no indica cuánto debes.", "Sí. Entender «parcial» no revela la cifra.", "El color no resuelve el pago."]}, {"variant": "C", "step": 5, "role": "transfer", "sentence": "La instrucción fue concisa: constaba de dos frases y omitía los detalles secundarios.", "question": "¿Cómo fue la instrucción?", "options": ["Breve y directa", "Muy extensa", "Imposible de entender"], "correct_index": 0, "feedback": ["Bien. «Dos frases» y sin detalles orientan el sentido.", "No era extensa.", "El texto no afirma que fuera incomprensible."]}, {"variant": "C", "step": 6, "role": "transfer", "sentence": "El correo indica que la cita se ha reprogramado, pero no da la nueva hora. Debes organizar tu traslado.", "question": "¿Qué conviene hacer?", "options": ["Usar la hora anterior sin preguntar", "Confirmar la nueva hora", "No acudir nunca más"], "correct_index": 1, "feedback": ["La cita cambió; la hora anterior puede fallar.", "Correcto. Necesitas el dato exacto para actuar.", "Reprogramar no equivale a cancelar."]}]$cases$::jsonb) loop
   insert into public.curriculum_cases(lesson_code,content_version,variant,step,role,sentence,question,options)
   values('1.4',1,item->>'variant',(item->>'step')::smallint,item->>'role',item->>'sentence',item->>'question',item->'options') returning id into new_case_id;
   insert into private.curriculum_answer_keys(case_id,correct_index,feedback)
   values(new_case_id,(item->>'correct_index')::smallint,item->'feedback');
   insert into private.curriculum_case_rubrics(case_id,error_codes,skill_code)
   values(new_case_id,(select jsonb_agg(case when n.i=(item->>'correct_index')::int then null else case when (item->>'step')::int=1 then 'connector_relation' when (item->>'step')::int in (4,6) then 'lookup_decision' else 'context_clue' end end order by n.i)
     from generate_series(0,2) n(i)),
     case when (item->>'step')::int=1 then 'sentence_connector' when (item->>'step')::int in (4,6) then 'vocabulary_decision' else 'vocabulary_context' end);
 end loop;
end $seed$;
insert into public.curriculum_lessons(code,block_number,position,title,mission,skill_code,is_published) values('1.C',1,5,'Cierre: comprender oraciones','Aplica las cuatro habilidades con oraciones nuevas, sin ayuda.','sentence_integration',true);
do $seed$
declare item jsonb; new_case_id uuid;
begin
 for item in select value from jsonb_array_elements($cases$[{"variant": "A", "step": 1, "role": "transfer", "sentence": "Después de revisar las fechas, Rosa cambió la reserva de la sala.", "question": "¿Qué hizo Rosa?", "options": ["Revisó una sala nueva", "Cambió la reserva", "Canceló todas las fechas"], "correct_index": 1, "feedback": ["Revisar ocurrió antes del cambio.", "Sí. Identificaste la acción principal.", "Cambiar no significa cancelar todo."]}, {"variant": "A", "step": 2, "role": "transfer", "sentence": "La autorización para usar el salón del viernes llegó por correo.", "question": "¿Qué palabras nombran cuál autorización llegó?", "options": ["La autorización para usar el salón del viernes", "llegó por correo", "del viernes llegó"], "correct_index": 0, "feedback": ["Correcto. La expresión completa identifica cuál era.", "Eso dice cómo llegó.", "La expresión corta una unidad de sentido."]}, {"variant": "A", "step": 3, "role": "transfer", "sentence": "La visita estaba confirmada, pero aún faltaba conocer la hora de entrada.", "question": "¿Qué faltaba pese a la confirmación?", "options": ["Confirmar la visita", "Conocer la hora de entrada", "Elegir otro edificio"], "correct_index": 1, "feedback": ["Ya estaba confirmada.", "Bien. «Pero» señala lo pendiente.", "No se menciona otro edificio."]}, {"variant": "A", "step": 4, "role": "transfer", "sentence": "El plan era provisional; lo revisarían tras escuchar a los vecinos.", "question": "¿Qué significa «provisional» aquí?", "options": ["Que puede cambiar", "Que es imposible de realizar", "Que ya es definitivo"], "correct_index": 0, "feedback": ["Sí. Se revisará después.", "La revisión no implica imposibilidad.", "Aún no es definitivo."]}, {"variant": "A", "step": 5, "role": "transfer", "sentence": "Aunque el paquete llegó tarde, Ana pudo entregar los materiales antes de la reunión.", "question": "¿Qué logró Ana pese al retraso?", "options": ["Aplazó la reunión", "Entregó los materiales a tiempo", "Devolvió el paquete"], "correct_index": 1, "feedback": ["La oración no dice que aplazara nada.", "Correcto. «Aunque» introduce el obstáculo superado.", "El paquete se utilizó."]}, {"variant": "A", "step": 6, "role": "transfer", "sentence": "El aviso indica que el registro es «prioritario», pero no explica si cierra hoy. Debes inscribirte dentro del plazo.", "question": "¿Qué necesitas comprobar?", "options": ["La fecha de cierre", "El tamaño de letra del aviso", "El nombre de quien lo imprimió"], "correct_index": 0, "feedback": ["Sí. La palabra no fija una fecha.", "Eso no determina el plazo.", "No resuelve cuándo cierra."]}, {"variant": "B", "step": 1, "role": "transfer", "sentence": "Tras comparar dos horarios, Luis escogió el turno de la mañana.", "question": "¿Qué decisión tomó Luis?", "options": ["Comparó el turno de la tarde", "Escogió la mañana", "Canceló todos los turnos"], "correct_index": 1, "feedback": ["Comparar fue el paso previo.", "Sí. Conservaste la decisión principal.", "No canceló los turnos."]}, {"variant": "B", "step": 2, "role": "transfer", "sentence": "Los materiales para la actividad del domingo están en el armario.", "question": "¿Qué palabras identifican los materiales?", "options": ["están en el armario", "Los materiales para la actividad del domingo", "para la actividad están"], "correct_index": 1, "feedback": ["Eso dice dónde están.", "Correcto. La expresión identifica cuáles.", "La combinación no forma una idea completa."]}, {"variant": "B", "step": 3, "role": "transfer", "sentence": "El recorrido era corto, pero tenía una escalera que el grupo no podía usar.", "question": "¿Qué cambia la segunda parte?", "options": ["El recorrido quizá no sirve al grupo", "El recorrido se volvió más largo", "El grupo ya usó la escalera"], "correct_index": 0, "feedback": ["Bien. «Pero» limita la ventaja de la ruta corta.", "La longitud sigue siendo corta.", "No pudieron usarla."]}, {"variant": "B", "step": 4, "role": "transfer", "sentence": "La respuesta fue escueta: solo decía «aprobado», sin detallar las condiciones.", "question": "¿Cómo fue la respuesta?", "options": ["Larga y explicativa", "Breve", "Contradictoria"], "correct_index": 1, "feedback": ["No incluyó condiciones detalladas.", "Correcto. El ejemplo permite inferir el sentido.", "No hay dos ideas en conflicto."]}, {"variant": "B", "step": 5, "role": "transfer", "sentence": "Marta llevó una copia porque el archivo falló, aunque la impresora casi no tenía tinta.", "question": "¿Qué hizo pese a la dificultad con la impresora?", "options": ["Llevó una copia", "Reparó el archivo", "Canceló la reunión"], "correct_index": 0, "feedback": ["Exacto. «Aunque» señala la dificultad superada.", "El archivo falló, no se dice que lo reparó.", "No hay cancelación."]}, {"variant": "B", "step": 6, "role": "transfer", "sentence": "La instrucción pide un documento «actualizado», pero no indica desde qué fecha se acepta. Tienes una versión antigua.", "question": "¿Qué conviene hacer?", "options": ["Entregarla sin preguntar", "Verificar qué fecha aceptan", "No llevar ningún documento"], "correct_index": 1, "feedback": ["El texto no permite asegurar que sirva.", "Sí. Aquí necesitas precisión antes de actuar.", "El requisito sigue vigente."]}, {"variant": "C", "step": 1, "role": "transfer", "sentence": "Al terminar la reunión, Elena envió el resumen al grupo.", "question": "¿Qué hizo Elena?", "options": ["Envió el resumen", "Preparó otra reunión", "Cambió el grupo"], "correct_index": 0, "feedback": ["Sí. Ese es el hecho principal.", "No se habla de otra reunión.", "No cambió al grupo."]}, {"variant": "C", "step": 2, "role": "transfer", "sentence": "La llave de la puerta del patio estaba en recepción.", "question": "¿Qué palabras indican cuál llave era?", "options": ["estaba en recepción", "de la puerta estaba", "La llave de la puerta del patio"], "correct_index": 2, "feedback": ["Eso indica dónde estaba.", "Esa combinación rompe el grupo.", "Correcto. Las palabras juntas identifican la llave."]}, {"variant": "C", "step": 3, "role": "transfer", "sentence": "El equipo tenía los datos, pero no había comprobado las cantidades.", "question": "¿Qué faltaba?", "options": ["Reunir los datos", "Comprobar las cantidades", "Borrar el informe"], "correct_index": 1, "feedback": ["Los datos ya estaban reunidos.", "Bien. La segunda parte marca la tarea pendiente.", "No se menciona borrar nada."]}, {"variant": "C", "step": 4, "role": "transfer", "sentence": "La fecha era tentativa: se confirmaría después de revisar la disponibilidad.", "question": "¿Qué significa «tentativa»?", "options": ["Todavía puede cambiar", "Es definitiva", "No existe ninguna fecha"], "correct_index": 0, "feedback": ["Correcto. Falta confirmarla.", "La revisión aún no termina.", "Sí hay una fecha propuesta."]}, {"variant": "C", "step": 5, "role": "transfer", "sentence": "Aunque faltaba una firma, el equipo pudo preparar los demás documentos.", "question": "¿Qué pudieron hacer?", "options": ["Reunir los otros documentos", "Obtener la firma faltante", "Enviar el expediente completo"], "correct_index": 0, "feedback": ["Sí. La firma pendiente no impidió preparar el resto.", "La firma seguía pendiente.", "No se afirma que enviaran todo."]}, {"variant": "C", "step": 6, "role": "transfer", "sentence": "El mensaje dice que la entrega será «pronto», pero necesitas esperar en casa a una hora específica.", "question": "¿Qué conviene hacer?", "options": ["Suponer que será al mediodía", "Solicitar el horario de entrega", "Ignorar el mensaje"], "correct_index": 1, "feedback": ["«Pronto» no fija una hora.", "Correcto. Necesitas un dato exacto.", "El mensaje orienta, pero no basta."]}]$cases$::jsonb) loop
   insert into public.curriculum_cases(lesson_code,content_version,variant,step,role,sentence,question,options)
   values('1.C',1,item->>'variant',(item->>'step')::smallint,item->>'role',item->>'sentence',item->>'question',item->'options') returning id into new_case_id;
   insert into private.curriculum_answer_keys(case_id,correct_index,feedback)
   values(new_case_id,(item->>'correct_index')::smallint,item->'feedback');
   insert into private.curriculum_case_rubrics(case_id,error_codes,skill_code)
   values(new_case_id,(select jsonb_agg(case when n.i=(item->>'correct_index')::int then null else case (item->>'step')::int when 1 then 'action_confusion' when 2 then 'chunk_boundary' when 3 then 'connector_relation' when 4 then 'context_clue' when 5 then 'connector_relation' else 'lookup_decision' end end order by n.i)
     from generate_series(0,2) n(i)),
     case (item->>'step')::int when 1 then 'sentence_action' when 2 then 'sentence_chunk' when 3 then 'sentence_connector' when 4 then 'vocabulary_context' when 5 then 'sentence_connector' else 'vocabulary_decision' end);
 end loop;
end $seed$;
create or replace function private.begin_curriculum_lesson(p_lesson_code text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  u uuid := auth.uid(); l public.curriculum_lessons%rowtype;
  a public.curriculum_attempts%rowtype; completed_count integer; chosen_variant text;
begin
  if u is null then raise exception 'Inicia sesión para aprender.' using errcode='28000'; end if;
  if not private.can_practice() then raise exception 'Tu acceso al programa no está activo.' using errcode='42501'; end if;
  select * into l from public.curriculum_lessons where code=p_lesson_code and is_published;
  if not found then raise exception 'La misión no está disponible.' using errcode='22023'; end if;
  if p_lesson_code in ('1.2','1.3','1.4','1.C') and not exists (select 1 from public.curriculum_attempts where user_id=u and lesson_code=case p_lesson_code when '1.2' then '1.1' when '1.3' then '1.2' when '1.4' then '1.3' else '1.4' end and status='completed') then
    raise exception 'Completa la lección anterior primero.' using errcode='22023';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(u::text||':'||p_lesson_code, 0));
  select * into a from public.curriculum_attempts
    where user_id=u and lesson_code=l.code and status='active' for update;
  if not found then
    select count(*) into completed_count from public.curriculum_attempts
      where user_id=u and lesson_code=l.code and status='completed';
    chosen_variant := case when completed_count % 3 = 0 then 'A' when completed_count % 3 = 1 then 'B' else 'C' end;
    if (select count(*) from public.curriculum_cases
      where lesson_code=l.code and content_version=l.content_version and variant=chosen_variant) <> 6 then
      raise exception 'Faltan casos para esta misión.' using errcode='22023';
    end if;
    insert into public.curriculum_attempts(user_id,lesson_code,content_version,variant)
      values(u,l.code,l.content_version,chosen_variant) returning * into a;
  end if;
  return private.curriculum_lesson_state(a.id);
end $$;

commit;
